import{_ as l,H as e,f as p,i as a}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"Q66 | 简历：简历中如何更好地阐述项目经验？","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q66｜简历：简历中如何更好地阐述项目经验？.md","filePath":"致程序员：AI百问百答/Q66｜简历：简历中如何更好地阐述项目经验？.md","lastUpdated":1795559851000}'),i={name:"致程序员：AI百问百答/Q66｜简历：简历中如何更好地阐述项目经验？.md"};function t(o,_,r,s,n,d){return e(),p("div",null,[..._[0]||(_[0]=[a('<h1 id="q66-简历-简历中如何更好地阐述项目经验" tabindex="-1">Q66 | 简历：简历中如何更好地阐述项目经验？ <a class="header-anchor" href="#q66-简历-简历中如何更好地阐述项目经验" aria-label="Permalink to &quot;Q66 | 简历：简历中如何更好地阐述项目经验？&quot;">​</a></h1><ul><li>作者介绍：许文强，前腾讯云 Kafka 技术负责人</li></ul><p>Q：简历中如何更好地阐述项目经验？</p><p>许文强：</p><p>简历中的项目经验有两个作用：</p><ol><li><p>让面试官知道你做过什么，你会做什么，你是什么角色，从而了解你这个人在团队中的定位、技术能力，进而对你这个人形成第一印象。</p></li><li><p>通过项目经验中提到的技术点、知识点，隐形地引导面试官提问。</p></li></ol><p>因此，阐述项目经验的时候，需要特别关注以下几点：</p><ol><li><p>不要写一堆，比如一下子写十几个项目经验，只需要挑跟面试岗位最匹配的项目经验写细致即可。也就是说，项目经验不要贪多，但是要跟岗位匹配度足够高，且描述细致，可以适当把项目经验的时间拉长一点点。</p></li><li><p>写清楚你是什么角色，你完成了哪些事情，比如完成了整体方案的设计，多个核心功能模块的开发。</p></li><li><p>项目经验里面写的东西，自己都需要懂且深入，因为好的面试官都是根据项目经验来提问，一旦项目回答不清楚，基本就挂了。</p></li><li><p>项目经验需要预埋一些问题点，比如你写了基于 Redis 实现分布式锁，那么面试官可能就会来问，“分布式锁如何实现”。这种就是引导面试官问问题。</p></li><li><p>适当提高自己在项目中的角色，比如负责人、Owner、架构师这种角色。</p></li><li><p>项目经验不要放一大串文字，应该分点说明。一般通过 1~6 这种序号说清楚你做了什么，这样简单清晰。另外，项目经验要精炼，不要让面试官觉得你在凑内容。</p></li></ol>',8)])])}const m=l(i,[["render",t]]);export{f as __pageData,m as default};
